mapper.select:
SELECT f.file_id AS fileId, f.uploader_user_id AS uploaderUserId, uploader.nickname AS uploaderNickname, uploader.email AS uploaderEmail, f.team_id AS teamId, t.name AS teamName, f.original_name AS originalName, f.content_type AS contentType, f.size_bytes AS sizeBytes, f.duration_seconds AS durationSeconds, f.status, f.hold_reason AS holdReason, f.deleted_at AS deletedAt, f.physical_delete_due_at AS physicalDeleteDueAt, f.created_at AS createdAt, ( SELECT COUNT(*) FROM work_item wi WHERE wi.file_id = f.file_id AND wi.status != 'DELETED' ) AS workReferenceCount, ( SELECT COUNT(*) FROM team_work_approval_request twr WHERE twr.file_id = f.file_id AND twr.status IN ('PENDING', 'APPROVED') ) AS requestReferenceCount FROM file_metadata f JOIN user_account uploader ON uploader.user_id = f.uploader_user_id LEFT JOIN team t ON t.team_id = f.team_id WHERE f.uploader_user_id = #{userId}
AND f.status = #{status}
ORDER BY f.created_at DESC, f.file_id DESC LIMIT #{limit}

SELECT f.file_id AS fileId, f.uploader_user_id AS uploaderUserId, uploader.nickname AS uploaderNickname, uploader.email AS uploaderEmail, f.team_id AS teamId, t.name AS teamName, f.original_name AS originalName, f.content_type AS contentType, f.size_bytes AS sizeBytes, f.duration_seconds AS durationSeconds, f.status, f.hold_reason AS holdReason, f.deleted_at AS deletedAt, f.physical_delete_due_at AS physicalDeleteDueAt, f.created_at AS createdAt, ( SELECT COUNT(*) FROM work_item wi WHERE wi.file_id = f.file_id AND wi.status != 'DELETED' ) AS workReferenceCount, ( SELECT COUNT(*) FROM team_work_approval_request twr WHERE twr.file_id = f.file_id AND twr.status IN ('PENDING', 'APPROVED') ) AS requestReferenceCount FROM file_metadata f JOIN user_account uploader ON uploader.user_id = f.uploader_user_id LEFT JOIN team t ON t.team_id = f.team_id WHERE 1 = 1
AND f.status = #{status}
AND ( f.original_name LIKE CONCAT('%', #{keyword}, '%') OR uploader.nickname LIKE CONCAT('%', #{keyword}, '%') OR uploader.email LIKE CONCAT('%', #{keyword}, '%') OR t.name LIKE CONCAT('%', #{keyword}, '%') )
AND f.uploader_user_id = #{uploaderUserId}
AND f.team_id = #{teamId}
ORDER BY f.created_at DESC, f.file_id DESC LIMIT #{limit}
